CREATE DATABASE IF NOT EXISTS lista18_dao;
USE lista18_dao;
CREATE TABLE IF NOT EXISTS alunos (id BIGINT PRIMARY KEY AUTO_INCREMENT, nome VARCHAR(120) NOT NULL, matricula VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS produtos (id BIGINT PRIMARY KEY AUTO_INCREMENT, descricao VARCHAR(180) NOT NULL, preco_unitario DECIMAL(12,2) NOT NULL, quantidade_estoque INT NOT NULL);
CREATE TABLE IF NOT EXISTS livros (id BIGINT PRIMARY KEY AUTO_INCREMENT, titulo VARCHAR(180) NOT NULL, autor VARCHAR(120) NOT NULL);
CREATE TABLE IF NOT EXISTS clientes (id BIGINT PRIMARY KEY AUTO_INCREMENT, nome VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL, cpf VARCHAR(14) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pedidos (id BIGINT PRIMARY KEY AUTO_INCREMENT, cliente_id BIGINT NOT NULL, data_pedido TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS itens_pedido (id BIGINT PRIMARY KEY AUTO_INCREMENT, pedido_id BIGINT NOT NULL, descricao VARCHAR(180) NOT NULL, quantidade INT NOT NULL, valor_unitario DECIMAL(12,2) NOT NULL, CONSTRAINT fk_itens_pedido FOREIGN KEY (pedido_id) REFERENCES pedidos(id));